script:
// Ferde hajítás – opcionális légellenállással és visszapattanással
// Projectile motion – optional air drag and bouncing
//   x = v₀·cos α·t        y = h + v₀·sin α·t − g·t²/2

// Vászon: szélesség, magasság (px), háttérszín / Canvas: width, height (px), background colour
stage(1000, 600, "#f7f9fc");
// Felirat a vászon bal felső sarkában / Caption in the top-left corner
title({hu: "Ferde hajítás", en: "Projectile motion"});
// A grafikon időablaka másodpercben / Chart time window in seconds
plotWindow(4);

// Csúszkák: azonosító, felirat (HU/EN), min, max, alapérték, lépés, egység – értékük: P.azonosító / Sliders: id, label (HU/EN), min, max, default, step, unit – value: P.id
param("v0",  {hu: "Kezdősebesség v₀", en: "Launch speed v₀"}, 1, 20, 14, 0.5, "m/s");
param("ang", {hu: "Hajítási szög α", en: "Launch angle α"}, 0, 90, 45, 1, "°");
param("h",   {hu: "Kezdőmagasság h", en: "Launch height h"}, 0, 10, 0, 0.5, "m");
param("g",   {hu: "Nehézségi gyorsulás g", en: "Gravity g"}, 1, 25, 9.81, 0.01, "m/s²");
param("k",   {hu: "Légellenállás k", en: "Air drag k"}, 0, 0.3, 0, 0.005, "1/m");
param("e",   {hu: "Visszapattanás e", en: "Restitution e"}, 0, 0.9, 0.4, 0.05, "");
// Kapcsolók: értékük true / false / Switches: their value is true / false
toggle("vec",   {hu: "Sebességvektorok", en: "Velocity vectors"}, true);
toggle("ideal", {hu: "Elméleti pálya (k = 0)", en: "Ideal path (k = 0)"}, true);
resetOn("v0", "ang", "h", "g");    // ezek változásakor újraindul / restart when these change
// Gomb a Vezérlők fülön / Button on the Controls tab
button({hu: "Újra dobás", en: "Throw again"}, reset);

// Fizikai világ: méterben, y felfelé; scale = px/m / Physics world: metres, y up; scale = px per metre
const W = world({gravity: P.g, scale: 20, origin: [60, 540], ground: true, restitution: P.e, friction: 0.3});
const r = 0.3;
const a = deg(P.ang);
// A hajított test / the projectile
const B = ball({x: 0, y: P.h + r, vx: P.v0 * cos(a), vy: P.v0 * sin(a), r: r, color: C.orange, trail: 600});
let ymax = B.y, range = null;

// Fizika: sok kis lépésben fut, dt a lépés hossza (s) / Physics: runs in many small steps, dt is the step length (s)
update((dt, t) => {
  W.e = P.e;
  if (P.k > 0) {                       // F = −k·m·|v|·v
    const v = hypot(B.vx, B.vy);
    B.applyForce(-P.k * B.m * v * B.vx, -P.k * B.m * v * B.vy);
  }
  ymax = max(ymax, B.y);
  // Első földet éréskor feljegyezzük a távolságot / record the range at the first touchdown
  if (range === null && B.onGround && t > 0.02) range = B.x;
});

// Rajzolás minden képkockán (szünetben is) / Drawing on every frame (also while paused)
draw(t => {
  // Tengelyek / axes
  for (let x = 0; x <= 45; x += 5) {
    line(wx(x), wy(0), wx(x), wy(0) + 8, {stroke: C.gray, lw: 1});
    text(x + " m", wx(x), wy(0) + 26, {size: 12, color: C.gray, align: "center"});
  }
  for (let y = 5; y <= 25; y += 5) {
    line(wx(0) - 6, wy(y), R_W(), wy(y), {stroke: "rgba(40,60,90,0.07)", lw: 1});
    text(y + " m", wx(0) - 10, wy(y) + 4, {size: 12, color: C.gray, align: "right"});
  }
  if (P.h > 0) rect(wx(-1.2), wy(P.h), ws(1.2), ws(P.h), {fill: "#e3e8ef", stroke: C.gray, lw: 1});

  // Elméleti parabola / ideal parabola
  if (P.ideal && P.ang < 89.5) {
    const pts = [];
    for (let x = 0; x < 60; x += 0.2) {
      const y = P.h + r + x * tan(a) - P.g * x * x / (2 * P.v0 * P.v0 * cos(a) ** 2);
      pts.push([wx(x), wy(y)]);
      if (y < r) break;
    }
    polyline(pts, {stroke: C.blue, lw: 1.5, dash: [6, 6], alpha: 0.8});
  }

  // Hajítószerkezet / launcher
  push(); translate(wx(0), wy(P.h + r)); rotate(-a);
  rect(-6, -7, 46, 14, {fill: C.ink, radius: 3});
  pop();

  // A fizikai világ (golyók, talaj) kirajzolása / Draw the physics world (balls, ground)
  drawWorld();

  if (P.vec) {
    const s = 6;   // px per m/s
    const X = wx(B.x), Y = wy(B.y);
    vector(X, Y, B.vx * s, 0, {stroke: C.blue, lw: 2}, "vx");
    vector(X, Y, 0, -B.vy * s, {stroke: C.green, lw: 2}, "vy");
    vector(X, Y, B.vx * s, -B.vy * s, {stroke: C.ink, lw: 2.5}, "v");
  }

  const vs = P.v0 * sin(a), vc = P.v0 * cos(a);
  // Mért értékek a Vezérlők fülön / Readouts on the Controls tab
  show({hu: "Idő t", en: "Time t"}, t, "s");
  show({hu: "Vízszintes hely x", en: "Horizontal position x"}, B.x, "m");
  show({hu: "Magasság y", en: "Height y"}, B.y - r, "m");
  show({hu: "Sebesség |v|", en: "Speed |v|"}, B.speed, "m/s");
  show({hu: "Legnagyobb magasság", en: "Maximum height"}, ymax - r, "m");
  show({hu: "Hajítás távolsága", en: "Range"}, range === null ? "…" : range, "m");
  show({hu: "Távolság (elmélet, k = 0)", en: "Range (theory, k = 0)"}, vc * (vs + sqrt(vs * vs + 2 * P.g * P.h)) / P.g, "m");

  // Élő grafikonok a vászon alatt / Live charts under the canvas
  plot({hu: "Magasság y", en: "Height y"}, B.y - r, {unit: "m", color: C.orange});
  plot({hu: "Függőleges sebesség vy", en: "Vertical velocity vy"}, B.vy, {unit: "m/s", color: C.green});
});

function R_W() { return 990; }
